-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.quiz_answers (
  user_id uuid default auth.uid() not null,
  round_id uuid not null,
  quiz_id text not null,
  section_id text not null,
  question_id text not null,
  position integer not null,
  chosen smallint,
  correct boolean not null,
  answered_at timestamp with time zone default now() not null,
  question_version smallint,
  constraint quiz_answers_pkey PRIMARY KEY (user_id, round_id, "position"),
  constraint quiz_answers_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint quiz_answers_user_id_round_id_fkey FOREIGN KEY (user_id, round_id) REFERENCES public.quiz_rounds(user_id, id) ON DELETE CASCADE,
  constraint quiz_answers_chosen_check CHECK (((chosen >= 0) AND (chosen <= 5))),
  constraint quiz_answers_position_check CHECK ((("position" >= 0) AND ("position" <= 9999))),
  constraint quiz_answers_question_id_check CHECK ((question_id ~ '^[A-Za-z0-9][A-Za-z0-9._+-]{0,63}$'::text)),
  constraint quiz_answers_question_version_check CHECK (((question_version >= 1) AND (question_version <= 32767))),
  constraint quiz_answers_quiz_id_check CHECK ((quiz_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
  constraint quiz_answers_section_id_check CHECK ((section_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);

CREATE INDEX quiz_answers_answered ON public.quiz_answers USING btree (answered_at);
CREATE INDEX quiz_answers_question ON public.quiz_answers USING btree (user_id, quiz_id, question_id);

CREATE TRIGGER quota_changes AFTER INSERT ON public.quiz_answers FOR EACH ROW EXECUTE FUNCTION public.quota_changes();

alter table public.quiz_answers enable row level security;

create policy "own quiz answers" on public.quiz_answers
  as permissive
  for all
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant delete, select on table public.quiz_answers to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.quiz_answers to service_role;
